import {METRIC_DETAILS,stationValue} from './explorer-model.mjs';
import {benchmark,composition,fixedScale,uniqueSamples} from './atlas-insights.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Number.isFinite(x)?new Intl.NumberFormat('ja-JP',{maximumFractionDigits:1}).format(x):'—';
const paths={food:'M5 3v7m3-7v7m-6-7v5a3 3 0 0 0 6 0M5 11v10M17 3v18m0-18c-4 3-4 8 0 8',shopping:'M5 8h14l1 13H4L5 8Zm3 0V6a4 4 0 0 1 8 0v2',students:'m2 8 10-5 10 5-10 5L2 8Zm4 3v6c4 3 8 3 12 0v-6m4-3v8',work:'M3 8h18v13H3V8Zm5 0V4h8v4M3 13h18m-11-2v4h4v-4',access:'M6 3h12v14H6V3Zm0 8h12M8 20l-2 2m10-2 2 2M9 15h.01M15 15h.01',all:'M3 21V9h6v12m0-16h7v16m0-10h5v10M1 21h22',people:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-7 10v-3a7 7 0 0 1 14 0v3m1-17a4 4 0 0 1 0 7m3 10v-3a7 7 0 0 0-2-5',cafe:'M4 5h13v7a6 6 0 0 1-12 0V5Zm13 1h2a3 3 0 0 1 0 6h-2M3 21h16',arrow:'M4 12h16m-6-6 6 6-6 6',map:'m2 6 6-3 8 3 6-3v15l-6 3-8-3-6 3V6Zm6-3v15m8-12v15'};
export function themeIcon(key){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${`<path d="${paths[key]||paths.all}"/>`}</svg>`;}
export function sectionTitle(n,title,sub=''){return `<div class="board-heading"><span class="step-number">${n}</span><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div></div>`;}
const tones={restaurants:['food','orange'],retail:['shopping','purple'],apparel:['shopping','pink'],employees:['work','blue'],university:['students','blue'],studentShare:['people','green'],population:['people','purple'],routeCount:['access','blue'],ridership:['access','blue']};
export function metricTile(data,students,s,k,state){const m=METRIC_DETAILS[k],v=stationValue(data,students,s,k),[icon,tone]=tones[k],b=benchmark(data,students,s,k,{scope:state.benchmark,line:state.line});return `<article class="theme-metric tone-${tone}"><span class="metric-symbol">${themeIcon(icon)}</span><div><div class="theme-metric-label">${m.label}<button data-definition="${k}" class="info-button" aria-label="${m.label}の定義">i</button></div><strong>${fmt(v)}${v===null?'':`<small>${m.unit}</small>`}</strong><span class="tile-period">${m.year}・${m.kind}</span>${k==='ridership'?'<p class="tile-baseline">集計基準は事業者ごとに異なります</p>':`<p class="tile-baseline">${esc(b.label)}の中央値<br><b>${fmt(b.median)} ${m.unit}</b></p>`}</div></article>`;}
export function themeSummary(data,students,s,state){const keys=state.theme==='students'?['university','studentShare','population','routeCount']:state.theme==='access'?['ridership','routeCount','restaurants','retail']:['restaurants','retail','apparel','employees'];const compositionData=composition(data,students,s);return `<div class="theme-metric-grid">${keys.map(k=>metricTile(data,students,s,k,state)).join('')}</div><p class="summary-scope">${state.theme==='access'?'駅利用は事業者別、路線数は同名・近接駅群。':'商業・人口は、駅のある約500m統計区画の都県別公表分。'}「—」は0ではありません。<button data-definition="${keys[0]}">定義と範囲</button></p>${state.theme!=='students'&&state.theme!=='access'&&compositionData?.total>0?`<div class="summary-composition"><b>飲食と小売の内訳</b><div class="composition-bar"><span style="width:${compositionData.foodShare}%"></span><span style="width:${compositionData.retailShare}%"></span></div><div><span>飲食 ${fmt(compositionData.foodShare)}%</span><span>小売 ${fmt(compositionData.retailShare)}%</span></div><small>この2業種の合計が分母。衣服店は小売に含みます。</small></div>`:''}`;}
export function boardRows(data,rows,state){const pinned=state.pins.map(id=>data.stations.find(s=>s.id===id)).filter(Boolean);if(pinned.length>=2)return {rows:pinned,label:'比較に選んだ駅'};const selected=rows.find(s=>s.id===state.station);return {rows:[...(selected?[selected]:[]),...uniqueSamples(rows.filter(s=>s.meshCode!==selected?.meshCode),'restaurants')].slice(0,5),label:'表示中の駅から・選択駅を先頭に表示'};}
function compareTable(data,students,ss,keys,state){return `<div class="board-table-wrap"><table class="board-table"><thead><tr><th>駅名</th>${keys.map(k=>`<th>${METRIC_DETAILS[k].label}<small>${METRIC_DETAILS[k].unit}・${METRIC_DETAILS[k].year}</small></th>`).join('')}</tr></thead><tbody>${ss.map(s=>`<tr class="${s.id===state.station?'selected-row':''}"><th><button data-pin="${s.id}" class="board-pin" aria-label="${esc(s.name)}を比較${state.pins.includes(s.id)?'から外す':'に追加'}" aria-pressed="${state.pins.includes(s.id)}">${state.pins.includes(s.id)?'✓':'＋'}</button><button data-station="${s.id}">${esc(s.name)}</button><small>${esc(s.operator)}</small></th>${keys.map(k=>`<td>${fmt(stationValue(data,students,s,k))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function studyCards(context,s){const records=context.educationSafety?.cramSchools?.records?.filter(x=>x.stations.some(t=>t.name===s?.name))||[];return records.length?records.map(x=>{const access=x.stations.find(t=>t.name===s.name);return `<article class="verified-school"><span class="facility-icon">${themeIcon('students')}</span><div><h3>${esc(x.name)}</h3><p>${esc(x.address)}</p>${access?.walkMinutes!=null?`<p>${esc(s.name)}駅${esc(access.exit||'')}から徒歩${access.walkMinutes}分（公式案内）</p>`:''}<a href="${esc(x.sourceUrl)}" target="_blank" rel="noopener noreferrer">公式校舎を見る ↗</a><small>${esc(x.checkedAt)} 確認</small></div></article>`}).join(''):'<div class="data-unavailable"><span class="facility-icon">'+themeIcon('students')+'</span><h3>この駅の確認記録は未収録</h3><p>学習塾がない、という意味ではありません。</p><button data-detail="context">収録済みの校舎を見る →</button></div>';}
export function themeBoard(data,students,context,rows,state){if(!rows.length)return '';const selection=boardRows(data,rows,state),ss=selection.rows,s=rows.find(s=>s.id===state.station)||ss[0],isStudent=state.theme==='students';
 if(isStudent){const max=fixedScale(data,students,'university').max;return `<section class="panel student-summary-board">${sectionTitle(3,'駅のサマリーを並べる',selection.label)}<div class="student-summary-strip">${ss.map(x=>{const v=stationValue(data,students,x,'university'),share=stationValue(data,students,x,'studentShare');return `<article class="student-summary-card ${x.id===state.station?'active':''}"><button class="summary-station-name" data-station="${x.id}">${esc(x.name)}</button><small>${esc(x.operator)}</small><span class="summary-student-icon">${themeIcon('students')}</span><strong>${fmt(v)}<small>${v===null?'':'人'}</small></strong><p>住んでいる大学・大学院生</p><div class="summary-share"><span>住民に占める割合</span><b>${fmt(share)}${share===null?'':'%'}</b></div><button data-profile="${x.id}" class="text-button">詳しく見る →</button></article>`}).join('')}</div><p class="board-footnote">2020年・駅所在500m区画の都県別公表分。大学の在籍人数や流入通学者数ではありません。</p></section><div class="student-theme-grid"><section class="panel">${sectionTitle(4,'学生が住む側面','居住人数と、住民に占める割合')}<div class="resident-chart">${ss.map(x=>{const v=stationValue(data,students,x,'university'),share=stationValue(data,students,x,'studentShare');return `<div><button data-station="${x.id}">${esc(x.name)}</button><span class="resident-bar">${v===null?'—':`<i style="width:${max>0?v/max*100:0}%"></i>`}</span><b>${fmt(v)}<small>${v===null?'':'人'}</small></b><span>${fmt(share)}${share===null?'':'%'}</span></div>`}).join('')}</div><p class="board-footnote">棒は人数、右端は住民比。人数の目盛りは全掲載対象で固定しています。</p></section><section class="panel">${sectionTitle(5,'学生が通う側面','日中に学生が集まる側面')}<div class="data-unavailable">${themeIcon('access')}<span class="data-state">未取得</span><h3>通学してくる学生数</h3><p>キャンパス別の在籍人数と、駅への通学経路を確認できた範囲から掲載します。</p><p class="board-footnote">住んでいる学生の人数で代用しません。</p></div></section><section class="panel">${sectionTitle(6,'学習する機会',s.name+'・公式情報を確認した学習塾')}${studyCards(context,s)}<p class="board-footnote">掲載校舎数は地域の総数ではありません。大学への導線・中学受験率は未取得です。</p></section></div><details class="panel theme-data-table"><summary>表示項目を選んだ比較表</summary>${compareTable(data,students,ss,state.columns,state)}</details>`;}
 return `<div class="commerce-theme-grid"><section class="panel">${sectionTitle(4,'数を比較する',selection.label)}${compareTable(data,students,ss,state.columns,state)}<div class="board-footer"><p>駅所在500m区画・都県別公表分。全産業の従業者数を商業従業者数と読み替えません。</p><button data-view="compare" data-station-comparison class="text-button">比較画面へ →</button></div></section><section class="panel">${sectionTitle(5,'街の中身をさらに知る','集計範囲ごとに、詳しいデータを見る')}<div class="regional-cards"><button data-detail="cafes" class="regional-card tone-green"><span class="facility-icon">${themeIcon('cafe')}</span><div><h3>喫茶・カフェ</h3><b>市区町村別の事業所数</b><p>2021年・自治体全体の公表値</p><span>自治体を選ぶ →</span></div></button><button data-detail="districts" class="regional-card tone-pink"><span class="facility-icon">${themeIcon('shopping')}</span><div><h3>商業地区の売上・売場面積</h3><b>公表された商業集積地区</b><p>売上2020年／売場面積2021年</p><span>商業地区を探す →</span></div></button></div><p class="board-footnote">どちらも駅所在の統計区画とは別の範囲です。個店率・大型商業施設総数・中心地密度は未算定です。</p></section></div>`;
}
